  assert.equal(state(g, 21, 1, 27).facing, "east");
  assert.equal(state(g, 20, 2, 27).type, "bottom");
  for (const z of [26, 28]) for (const y of [1, 2]) assert.equal(at(g, 20, y, z), "minecraft:air", `lane z=${z} y=${y}`);
}

